# Legacy target "rear" is now the matching front lid.
shared = part("front")
lid_thickness = param("rear_floor_thickness", 1.6)
lid_width = shared.pocket_width - 2 * shared.lid_clearance
lid_bottom_y = shared.pocket_bottom_y + shared.lid_clearance
lid_top_y = shared.mouth_y
lid_height = lid_top_y - lid_bottom_y
lid_radius = shared.outer_radius
lid_profile = Pos(0, (lid_top_y + lid_bottom_y) / 2) * Rectangle(lid_width, lid_height)
# Only lower corners retain R2; the two insertion-end corners are square.
bottom_vertices = [v for v in lid_profile.vertices() if abs(v.Y - lid_bottom_y) < 0.000001]
assert len(bottom_vertices) == 2
lid_profile = fillet(bottom_vertices, radius=lid_radius)
lid_shape = extrude(lid_profile, amount=lid_thickness)
assert lid_width > shared.cavity_width
assert lid_bottom_y < -shared.cavity_height / 2
assert abs(lid_thickness - shared.recess_depth) < 0.000001, "Lid must match recess depth for a flush face"
assert len(lid_shape.solids()) == 1
print(f"Front lid {lid_width:.3f} x {lid_height:.3f} x {lid_thickness:.3f}, side gap {shared.lid_clearance:.3f}, flush seated face")
lid_shape.color = srgb("#e6e6e6")



