LOGO_SPEC = {"x_min":-0.5,"width":0.2853399,"height":0.1340504758,"raw_size":[415,194],"bars":[[[0,0],[237,120],[237,188],[0,68]],[[89,3],[326,123],[326,191],[89,71]],[[178,6],[415,126],[415,194],[178,74]]],"groove_paths":[[[89,3],[89,71],[237,145.9367088607595]],[[178,6],[178,74],[326,148.9367088607595]]]}
relief_width = param("front_relief_width",88.0)
relief_height = param("front_relief_height",1.5)
relief_center_x = param("front_relief_center_x",0.0)
relief_center_y = param("front_relief_center_y",-1.165)
relief_embed = param("front_relief_embed",0.02)
groove_width = param("front_logo_groove_width",0.3)
groove_depth = param("front_logo_groove_depth",0.6)
def artwork_point(u,v):
    return (relief_center_x+v*relief_width,relief_center_y-u*relief_width)
def lift_profile(profile):
    return Pos(0,0,lid_thickness-relief_embed)*extrude(profile,amount=relief_height+relief_embed,dir=(0,0,1))
letter_solids=[]
for glyph in REFERENCE_GLYPHS:
    wires=[]
    for contour in glyph["loops"]:
        edges=[]
        previous=contour["start"]
        for segment in contour["segments"]:
            pts=[artwork_point(u,v)for u,v in [previous]+segment]
            edges.append(Line(*pts)if len(pts)==2 else Bezier(*pts))
            previous=segment[-1]
        wires.append(Wire(edges))
    glyph_face=Face(wires[0])
    for hole in wires[1:]:
        glyph_face=glyph_face-Face(hole)
    letter_shape=lift_profile(glyph_face)
    assert len(letter_shape.solids())==1
    letter_solids.extend(letter_shape.solids())
assert len(letter_solids)==9
letter_union=letter_solids[0].fuse(*letter_solids[1:])
assert len(letter_union.solids())==9,"Letters must remain separate without accidental joins"
def raw_logo_point(p):
    return (LOGO_SPEC["x_min"]+p[0]/415.0*LOGO_SPEC["width"],(p[1]/194.0-.5)*LOGO_SPEC["height"])
bar_profiles=[Polygon(*[artwork_point(*raw_logo_point(p))for p in raw_bar],align=None)for raw_bar in LOGO_SPEC["bars"]]
logo_bars=[lift_profile(p)for p in bar_profiles]
logo_shape=logo_bars[0].fuse(*logo_bars[1:])
def rear_only_band(raw_path):
    a,b,c=[(u*relief_width,v*relief_width)for u,v in [raw_logo_point(p)for p in raw_path]]
    def unit(p,q):
        dx,dy=q[0]-p[0],q[1]-p[1]
        d=(dx*dx+dy*dy)**.5
        return dx/d,dy/d
    d0,d1=unit(a,b),unit(b,c)
    n0,n1=(-d0[1],d0[0]),(-d1[1],d1[0])
    denom=1+n0[0]*n1[0]+n0[1]*n1[1]
    m=((n0[0]+n1[0])*groove_width/denom,(n0[1]+n1[1])*groove_width/denom)
    a=(a[0]-2*groove_width*d0[0],a[1]-2*groove_width*d0[1])
    c=(c[0]+2*groove_width*d1[0],c[1]+2*groove_width*d1[1])
    # Entire band is to the left/rear of the foreground-bar edge.
    points=[a,b,c,(c[0]+groove_width*n1[0],c[1]+groove_width*n1[1]),(b[0]+m[0],b[1]+m[1]),(a[0]+groove_width*n0[0],a[1]+groove_width*n0[1])]
    return Polygon(*[artwork_point(u/relief_width,v/relief_width)for u,v in points],align=None)
for i,path in enumerate(LOGO_SPEC["groove_paths"]):
    visible_rear=bar_profiles[i]
    for foreground in bar_profiles[i+1:]:
        visible_rear=visible_rear-foreground
    cut_region=rear_only_band(path)&visible_rear
    cutter=Pos(0,0,lid_thickness+relief_height-groove_depth)*extrude(cut_region,amount=groove_depth+relief_embed,dir=(0,0,1))
    logo_shape=logo_shape-cutter
assert len(logo_shape.solids())==1
assert all(edge.geom_type==GeomType.LINE for edge in logo_shape.edges())
front_bar_retained=logo_shape&logo_bars[-1]
assert abs(front_bar_retained.volume-logo_bars[-1].volume)<0.000001,"Foreground bar must remain completely uncut"
assert 0<groove_depth<relief_height and groove_width>0
relief_solids=list(logo_shape.solids())+letter_solids
relief_shape=Compound(children=relief_solids)
relief_shape.color=srgb("#111111")
bounds=relief_shape.bounding_box()
assert bounds.min.X>-lid_width/2 and bounds.max.X<lid_width/2
assert bounds.min.Y>lid_bottom_y and bounds.max.Y<lid_top_y
assert abs(bounds.max.Z-lid_thickness-relief_height)<0.00001
assert all(s.is_valid for s in relief_solids),"All relief inputs must be valid"
fused_cover=lid_shape.fuse(*relief_solids)
assert len(fused_cover.solids())==1
print(f"New-image glyphs: 9 separate; original proportions and kerning; rear-only seams {groove_width} wide, {groove_depth} deep; foreground bar retained exactly; relief height {relief_height}")
# Deliver one watertight front-cover solid including all raised artwork.
fused_cover=fused_cover.clean()
assert len(fused_cover.solids())==1,"Front cover must contain exactly one solid"
assert fused_cover.is_valid,"Fused front-cover geometry must be valid"
assert abs(fused_cover.bounding_box().min.Z)<0.00001
assert abs(fused_cover.bounding_box().max.Z-lid_thickness-relief_height)<0.00001
fused_cover.color=srgb("#e6e6e6")
for face in fused_cover.faces():
    if face.center().Z>lid_thickness+0.00001:
        face.color=srgb("#111111")
print(f"Unified front cover: {len(fused_cover.solids())} solid; relief {relief_height} mm; total thickness {lid_thickness+relief_height} mm")
publish("rear_panel",fused_cover,"前盖 · 一体浮雕",material="pla")
